 {title:'魔域 · 狮驼与无底',short:'狮驼魔域',sub:'狮驼岭、比丘国与隐雾山',ids:range(86,93),color:0x85949a},
 {title:'归途 · 九灵与月华',short:'九灵月华',sub:'竹节山、青龙山与天竺国',ids:range(94,107),color:0xa18a9b}
