const byId=new Map(DATA.map(a=>[a.id,a]));halls.forEach((h,i)=>h.ids.forEach(id=>byId.get(id).hall=i));const order=halls.flatMap(h=>h.ids);
let visited=new Set();try{visited=new Set(JSON.parse(localStorage.getItem('xiyou-visited')||'[]').filter(id=>byId.has(id)));}catch{}
let current=0,selected='001',tour=-1,night=false,renderer,scene,camera,yaw=-.34,pitch=.035,travel=null,keys={},drag=null,previous=performance.now(),hovered=null;
