const ray=new T.Raycaster(),pointer=new T.Vector2(),loader=new T.TextureLoader(),reduced=matchMedia('(prefers-reduced-motion:reduce)').matches;
function toast(t){$('toast').textContent=t;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,3500);}
function dismiss(){$('welcome').classList.add('dismissed');}
function busy(){return !!document.querySelector('dialog[open]');}
function open(id){keys={};drag=null;$('hover').hidden=true;if(!$(id).open)$(id).showModal();}
function close(id){$(id).close();if(!busy())$('scene').focus({preventScroll:true});}
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>close(b.dataset.close));
document.querySelectorAll('dialog').forEach(d=>{d.addEventListener('click',e=>{if(e.target!==d)return;let r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();});d.addEventListener('close',()=>keys={});});
function updateVisited(){$('visited').textContent=`已赏 ${visited.size} / 114`;try{localStorage.setItem('xiyou-visited',JSON.stringify([...visited]));}catch{}}
function detail(id){const a=byId.get(id);if(!a)return;selected=id;visited.add(id);updateVisited();$('artImg').src=`assets/${id}-full.webp`;$('artImg').alt=`${a.name}针织羊毛全身作品`;$('name').textContent=a.name;$('chapter').textContent=`${String(a.hall+1).padStart(2,'0')} / ${a.chapter}`;$('identity').textContent=a.identity;$('story').textContent=a.story;$('artNo').textContent=`NO. ${id}`;for(let f of ['traits','relations'])$(f).replaceChildren(...a[f].map(t=>{let li=document.createElement('li');li.textContent=t;return li;}));$('source').href=a.sourceUrl;$('detail').querySelector('article').scrollTop=0;open('detail');}
function renderGrid(){let q=$('search').value.trim().toLowerCase(),cat=$('filter').value;let list=DATA.filter(a=>(!cat||a.category===cat)&&(!q||[a.name,a.chapter,a.identity,a.story].join(' ').toLowerCase().includes(q)));$('results').textContent=`${list.length} 位角色${q?' · “'+q+'”':''}`;$('grid').replaceChildren(...list.map(a=>{let b=document.createElement('button');b.className='card';b.setAttribute('aria-label',`${a.name}，查看角色介绍`);let img=document.createElement('img');img.src=`assets/${a.id}-thumb.webp`;img.alt=a.name;img.loading='lazy';let strong=document.createElement('strong');strong.textContent=a.name;let small=document.createElement('small');small.textContent=`${a.id} / ${a.chapter}`;b.append(img,strong,small);b.onclick=()=>detail(a.id);return b;}));}
function browse(){renderGrid();open('collection');setTimeout(()=>$('search').focus(),30);}
$('search').oninput=renderGrid;$('filter').onchange=renderGrid;$('browseBtn').onclick=$('fallbackBtn').onclick=browse;$('mapBtn').onclick=()=>open('map');
function updateHall(i){current=i;let h=halls[i];$('hallNo').textContent=String(i+1).padStart(2,'0');$('hallName').textContent=h.title;$('hallSub').textContent=`${h.ids.length} 幅作品 / ${h.sub}`;document.querySelectorAll('[data-hall]').forEach(b=>b.classList.toggle('active',+b.dataset.hall===i));}
function initNav(){halls.forEach((h,i)=>{let b=document.createElement('button');b.dataset.hall=i;b.innerHTML=`<span>0${i+1}</span>${h.short}`;b.onclick=()=>goHall(i);$('hallTabs').append(b);let m=document.createElement('button');m.className='room';m.dataset.hall=i;m.innerHTML=`<span>0${i+1}</span><div><strong>${h.title}</strong><small>${h.sub}</small></div><b>${h.ids.length} 幅 →</b>`;m.onclick=()=>{close('map');goHall(i);};$('rooms').append(m);});updateHall(0);}
function moveTo(pos,target,duration=650){if(!camera)return;let d=target.clone().sub(pos),ty=Math.atan2(-d.x,-d.z),tp=Math.atan2(d.y,Math.hypot(d.x,d.z));let turn=ty-yaw;while(turn>Math.PI)turn-=Math.PI*2;while(turn<-Math.PI)turn+=Math.PI*2;travel={from:camera.position.clone(),to:pos,fy:yaw,ty:yaw+turn,fp:pitch,tp,start:performance.now(),duration:reduced?0:duration};keys={};}
function goHall(i){i=(i+7)%7;dismiss();stopTour();if(camera){let z=-i*step;camera.position.set(0,eye,z+8);yaw=-.15;pitch=.04;travel=null;loadHall(i);}updateHall(i);$('scene').focus();}
function focus(id){dismiss();let f=artworks.get(id);if(!f)return;let h=byId.get(id).hall;if(h!==current){camera.position.set(0,eye,-h*step+6);updateHall(h);}loadHall(h);let pos=f.position.clone().add(f.normal.clone().multiplyScalar(Math.max(3.1,f.h*1.3)));pos.y=eye;moveTo(pos,f.position.clone());}
function startTour(){tour=halls.slice(0,current).reduce((n,h)=>n+h.ids.length,0);tourStep(0);}
function tourStep(d){tour=(tour+d+114)%114;focus(order[tour]);$('tourBar').hidden=false;$('tourLabel').textContent=`${tour+1} / 114 · ${byId.get(order[tour]).name}`;$('tourBtn').textContent='■ 结束导览';}
function stopTour(){tour=-1;$('tourBar').hidden=true;$('tourBtn').textContent='▷ 作品导览';}
$('enterBtn').onclick=()=>{dismiss();$('scene').focus();toast('拖动转头，WASD 或方向键移动；点击画作阅读故事');};$('prevHall').onclick=()=>goHall(current-1);$('nextHall').onclick=()=>goHall(current+1);$('homeBtn').onclick=()=>goHall(current);$('tourBtn').onclick=()=>tour<0?startTour():stopTour();$('introTour').onclick=startTour;$('tourPrev').onclick=()=>tourStep(-1);$('tourNext').onclick=()=>tourStep(1);$('tourClose').onclick=stopTour;$('tourOpen').onclick=()=>detail(order[tour]);
$('prevArt').onclick=()=>detail(order[(order.indexOf(selected)+113)%114]);$('nextArt').onclick=()=>detail(order[(order.indexOf(selected)+1)%114]);$('locate').onclick=()=>{document.querySelectorAll('dialog[open]').forEach(d=>d.close());focus(selected);toast(`已定位：${byId.get(selected).name}`);};
$('fullBtn').onclick=async()=>{try{document.fullscreenElement?await document.exitFullscreen():await document.documentElement.requestFullscreen();}catch{toast('当前浏览器不支持全屏');}};
let zoom=1,px=0,py=0,zd=null;function scale(z){zoom=Math.max(1,Math.min(5,z));if(zoom===1)px=py=0;$('zoomImg').style.transform=`translate(${px}px,${py}px) scale(${zoom})`;$('zoomReset').textContent=`${Math.round(zoom*100)}%`;}
$('zoomBtn').onclick=()=>{$('zoomImg').src=$('artImg').src;$('zoomImg').alt=$('artImg').alt;$('download').href=`assets/${selected}-full.webp`;$('download').download=`${selected}_${byId.get(selected).name}.webp`;scale(1);open('zoom');};$('zoomIn').onclick=()=>scale(zoom+.4);$('zoomOut').onclick=()=>scale(zoom-.4);$('zoomReset').onclick=()=>scale(1);$('zoomStage').addEventListener('wheel',e=>{e.preventDefault();scale(zoom-e.deltaY*.002);},{passive:false});$('zoomStage').onpointerdown=e=>{zd={x:e.clientX,y:e.clientY,px,py};$('zoomStage').setPointerCapture(e.pointerId);};$('zoomStage').onpointermove=e=>{if(zd){px=zd.px+e.clientX-zd.x;py=zd.py+e.clientY-zd.y;scale(zoom);}};$('zoomStage').onpointerup=$('zoomStage').onpointercancel=()=>zd=null;
const material=c=>new T.MeshStandardMaterial({color:c,roughness:.82});
function box(w,h,d,m,x,y,z,parent=scene){let o=new T.Mesh(new T.BoxGeometry(w,h,d),m);o.position.set(x,y,z);parent.add(o);if(wallMats.includes(m))occluders.push(o);return o;}
function texture(w,h,draw){let c=document.createElement('canvas');c.width=w;c.height=h;draw(c.getContext('2d'),w,h);let t=new T.CanvasTexture(c);t.colorSpace=T.SRGBColorSpace;return t;}
function label(lines,small=false){return texture(1024,small?256:512,(c,w,h)=>{c.fillStyle='#ebeadd';c.fillRect(0,0,w,h);c.textAlign='center';lines.forEach((line,i)=>{c.font=`${i===0?(small?65:92):(small?34:37)}px ${i===0?'serif':'sans-serif'}`;c.fillStyle=i===0?'#43533b':'#8b947c';c.fillText(line,w/2,h*(i===0?.44:.77));});});}
function plane(w,h,map,x,y,z,ry=0,parent=scene){let o=new T.Mesh(new T.PlaneGeometry(w,h),new T.MeshBasicMaterial({map,toneMapped:false}));o.position.set(x,y,z);o.rotation.y=ry;parent.add(o);return o;}
function plant(x,z,g){let pot=new T.Mesh(new T.CylinderGeometry(.4,.29,.62,20),material(0xb3a58e));pot.position.set(x,.31,z);g.add(pot);let trunk=new T.Mesh(new T.CylinderGeometry(.04,.06,1.9,8),material(0x7b7454));trunk.position.set(x,1.3,z);g.add(trunk);let m=material(0x687954);for(let i=0;i<13;i++){let a=i*2.4,r=.25+(i%4)*.13,l=new T.Mesh(new T.SphereGeometry(.3,8,6),m);l.scale.set(1,.3,1.4);l.position.set(x+Math.cos(a)*r,1.25+i*.08,z+Math.sin(a)*r);l.rotation.z=(i%2?.4:-.4);g.add(l);}}
function art(id,x,y,z,ry,w,g){let h=w*4/3,ag=new T.Group();ag.position.set(x,y,z);ag.rotation.y=ry;g.add(ag);box(w+.2,h+.2,.13,material(0x756446),0,0,0,ag);box(w+.09,h+.09,.16,material(0xc5b48d),0,0,.025,ag);box(w+.035,h+.035,.17,material(0xf6f3e7),0,0,.05,ag);let face=plane(w,h,null,0,0,.15,0,ag);face.material.color.set(0xf8f7ef);face.userData.id=id;hits.push(face);let a=byId.get(id);plane(Math.min(w,1.5),.375,label([`${id}  ${a.name}`,a.chapter],true),0,-h/2-.32,.02,0,ag);box(w*.65,.055,.18,material(0x626b58),0,h/2+.37,.2,ag);box(w*.6,.02,.15,new T.MeshBasicMaterial({color:0xffe0aa}),0,h/2+.335,.22,ag);let pos=new T.Vector3();ag.getWorldPosition(pos);artworks.set(id,{mesh:face,position:pos,normal:new T.Vector3(Math.sin(ry),0,Math.cos(ry)),h});}
function wood(){return texture(1024,1024,(c,w,h)=>{for(let r=0;r<16;r++)for(let j=-1;j<5;j++){let k=(r*7+j*11+80)%13,x=j*256+(r%2)*128,y=r*64;c.fillStyle=`rgb(${190+k},${174+k},${145+k})`;c.fillRect(x,y,256,64);c.strokeStyle='#6c664322';c.strokeRect(x,y,256,64);for(let n=0;n<5;n++){c.strokeStyle='#796e3913';c.beginPath();c.moveTo(x,y+10+n*11);c.bezierCurveTo(x+75,y+5+n*11,x+180,y+17+n*11,x+256,y+10+n*11);c.stroke();}}});}
function init3D(){try{renderer=new T.WebGLRenderer({canvas:$('scene'),antialias:true,powerPreference:'high-performance'});}catch(e){renderer=new CompatibleRenderer();console.info('Using compatible 3D rendering');}
 renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.setSize(innerWidth,innerHeight);renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.05;scene=new T.Scene();scene.background=new T.Color(0xe9e6d9);scene.fog=new T.Fog(0xe9e6d9,30,65);camera=new T.PerspectiveCamera(57,innerWidth/innerHeight,.08,90);camera.rotation.order='YXZ';camera.position.set(-1.6,eye,6.8);
 let hemi=new T.HemisphereLight(0xfffbef,0x948267,2.1);scene.add(hemi);let sun=new T.DirectionalLight(0xffedce,2.2);sun.position.set(5,10,8);scene.add(sun);let fill=new T.DirectionalLight(0xe2e9e3,1.2);fill.position.set(-7,4,-3);scene.add(fill);let wt=wood();wt.wrapS=wt.wrapT=T.RepeatWrapping;wt.repeat.set(3,5);wt.anisotropy=Math.min(4,renderer.capabilities.getMaxAnisotropy());let fm=new T.MeshStandardMaterial({map:wt,roughness:.75});
 halls.forEach((h,hi)=>{let g=new T.Group();g.position.z=-hi*step;scene.add(g);groups.push(g);let wm=material(0xe3e1d2),rm=material(0xe8e6dc),trim=material(0xd2ceb9),rail=material(0x8a8c77);wallMats.push(wm);roofMats.push(rm);box(20,.12,30,fm,0,-.09,0,g);box(.25,6.8,30,wm,-10,3.4,0,g);box(.25,6.8,30,wm,10,3.4,0,g);box(20,.15,30,rm,0,6.85,0,g);
 for(let s of [-1,1]){box(7,6.8,.28,wm,s*6.5,3.4,-15,g);box(.13,4.2,.4,trim,s*3.05,2.1,-14.8,g);box(.1,.16,30,trim,s*9.8,.12,0,g);box(.055,.06,28,rail,s*8.5,6.45,0,g);}box(6,2.6,.28,wm,0,5.5,-15,g);box(6.2,.16,.4,trim,0,4.25,-14.8,g);if(hi===0)box(20,6.8,.25,wm,0,3.4,15,g);if(hi===6)box(6,4.2,.28,wm,0,2.1,-15,g);
 for(let z of [-9,0,9])box(10,.03,4.5,new T.MeshBasicMaterial({color:0xfffcf0}),0,6.74,z,g);
 for(let x of [-8.5,8.5])for(let z=11;z>-13;z-=3){let l=new T.Mesh(new T.CylinderGeometry(.1,.12,.3,10),rail);l.rotation.z=x>0?-.5:.5;l.position.set(x,6.25,z);g.add(l);}
 plane(4.8,2.4,label([h.title.split(' · ')[1],`HALL 0${hi+1} / ${h.ids.length} WORKS`]),0,5.5,-14.8,0,g);
 art(h.ids[0],-6.45,3.25,-14.75,0,3.05,g);art(h.ids[1],6.45,3.25,-14.75,0,3.05,g);let rest=h.ids.slice(2),num=Math.ceil(rest.length/2),spacing=num>1?22/(num-1):0;rest.forEach((id,i)=>{let side=i%2===0?-1:1,j=Math.floor(i/2),w=num>9?[1.45,1.7,1.6][j%3]:[2.0,1.65,2.2,1.85][j%4];art(id,side*9.77,3+(j%3===0?.12:0),11-j*spacing,side<0?Math.PI/2:-Math.PI/2,w,g);});
 for(let s of [-1,1]){box(2.8,.12,1.05,material(0xb5a98a),s*3.7,.7,2,g);box(.16,.65,.9,material(0x867454),s*3.7-1,.32,2,g);box(.16,.65,.9,material(0x867454),s*3.7+1,.32,2,g);benches.push({x:s*3.7,z:2-hi*step});}plant(-8,12.7,g);plant(8,12.7,g);let med=new T.Mesh(new T.CircleGeometry(1.15,40),new T.MeshBasicMaterial({color:h.color,transparent:true,opacity:.19}));med.rotation.x=-Math.PI/2;med.position.set(0,.003,7);g.add(med);
 });
 $('lightBtn').onclick=()=>{night=!night;document.body.classList.toggle('night',night);hemi.intensity=night?.65:2.1;sun.intensity=night?.85:2.2;fill.intensity=night?.38:1.2;wallMats.forEach(m=>m.color.set(night?0x65745e:0xe3e1d2));roofMats.forEach(m=>m.color.set(night?0x455345:0xe8e6dc));renderer.toneMappingExposure=night?.9:1.05;scene.background.set(night?0x293b2e:0xe9e6d9);scene.fog.color.copy(scene.background);};loadHall(0);controls();renderer.setAnimationLoop(animate);setTimeout(()=>$('loader').hidden=true,15000);
}
function loadHall(hi){if(!renderer)return;for(let h=Math.max(0,hi-1);h<=Math.min(6,hi+1);h++)for(let id of halls[h].ids){if(textures.has(id)||pending.has(id))continue;pending.add(id);loader.load(`assets/${id}-wall.webp`,t=>{pending.delete(id);if(Math.abs(byId.get(id).hall-current)>1){t.dispose();return;}t.colorSpace=T.SRGBColorSpace;t.anisotropy=Math.min(4,renderer.capabilities.getMaxAnisotropy());textures.set(id,t);let m=artworks.get(id).mesh.material;m.map=t;m.color.set(0xffffff);m.needsUpdate=true;let n=halls[current].ids.filter(i=>textures.has(i)).length;$('loader').textContent=`本厅作品 ${n} / ${halls[current].ids.length}`;if(n===halls[current].ids.length)$('loader').hidden=true;},undefined,()=>{pending.delete(id);toast('作品加载失败，请刷新页面重试');});}for(let[id,t]of textures)if(Math.abs(byId.get(id).hall-hi)>1){let m=artworks.get(id).mesh.material;m.map=null;m.needsUpdate=true;t.dispose();textures.delete(id);}}
function resize(){if(renderer){renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();}}window.addEventListener('resize',resize);
function pick(x,y){if(!camera)return;pointer.set(x/innerWidth*2-1,1-y/innerHeight*2);ray.setFromCamera(pointer,camera);let list=ray.intersectObjects([...hits,...occluders]);for(let hit of list){let obj=hit.object,p=obj,visible=true;while(p){if(!p.visible)visible=false;p=p.parent;}if(!visible)continue;if(hit.distance>28)return;return obj.userData.id;}}
function allowed(x,z){if(Math.abs(x)>9.4||z>14||z<-6*step-14)return false;for(let i=0;i<6;i++)if(Math.abs(z+15+i*step)<.62&&Math.abs(x)>2.55)return false;for(let b of benches)if(Math.abs(x-b.x)<1.7&&Math.abs(z-b.z)<.82)return false;return true;}
function walk(side,forward){let dx=Math.cos(yaw)*side-Math.sin(yaw)*forward,dz=-Math.sin(yaw)*side-Math.cos(yaw)*forward,n=Math.max(1,Math.ceil(Math.hypot(dx,dz)/.15));for(let i=0;i<n;i++){let x=camera.position.x+dx/n,z=camera.position.z+dz/n;if(allowed(x,camera.position.z))camera.position.x=x;if(allowed(camera.position.x,z))camera.position.z=z;}}
function controls(){let c=$('scene');c.onpointerdown=e=>{if(busy())return;dismiss();drag={x:e.clientX,y:e.clientY,d:0};c.setPointerCapture(e.pointerId);c.focus();};c.onpointermove=e=>{if(drag){let dx=e.clientX-drag.x,dy=e.clientY-drag.y;drag.d+=Math.abs(dx)+Math.abs(dy);if(drag.d>5){travel=null;yaw-=dx*.003;pitch=Math.max(-.65,Math.min(.65,pitch-dy*.0025));}drag.x=e.clientX;drag.y=e.clientY;}else if(!busy()){let id=pick(e.clientX,e.clientY);if(id!==hovered){hovered=id;$('hover').hidden=!id;if(id)$('hover').textContent=`${byId.get(id).name} · 点击查看`;c.style.cursor=id?'pointer':'grab';}}};c.onpointerup=e=>{if(drag&&drag.d<8){let id=pick(e.clientX,e.clientY);if(id)detail(id);}drag=null;};c.onpointercancel=()=>drag=null;c.addEventListener('wheel',e=>{if(busy())return;e.preventDefault();dismiss();travel=null;walk(0,-e.deltaY*.007);},{passive:false});
 window.addEventListener('keydown',e=>{if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||busy())return;let k=e.key.toLowerCase(),map={arrowup:'w',arrowdown:'s',arrowleft:'a',arrowright:'d'};k=map[k]||k;if(['w','a','s','d','shift'].includes(k)){e.preventDefault();keys[k]=true;travel=null;dismiss();}if(k==='/'){e.preventDefault();browse();}if(k==='e'){let id=pick(innerWidth/2,innerHeight/2);if(id)detail(id);}});window.addEventListener('keyup',e=>{let map={arrowup:'w',arrowdown:'s',arrowleft:'a',arrowright:'d'};delete keys[map[e.key.toLowerCase()]||e.key.toLowerCase()];});window.addEventListener('blur',()=>{keys={};drag=null;});
 document.querySelectorAll('[data-move]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();keys[b.dataset.move]=true;b.classList.add('active');b.setPointerCapture(e.pointerId);dismiss();travel=null;};b.onpointerup=b.onpointercancel=()=>{delete keys[b.dataset.move];b.classList.remove('active');};});}
function animate(now){let dt=Math.min((now-previous)/1000,.045);previous=now;if(!busy()){if(travel){let t=travel.duration?Math.min(1,(now-travel.start)/travel.duration):1,s=t*t*(3-2*t);camera.position.lerpVectors(travel.from,travel.to,s);yaw=T.MathUtils.lerp(travel.fy,travel.ty,s);pitch=T.MathUtils.lerp(travel.fp,travel.tp,s);if(t===1)travel=null;}else{let f=(keys.w?1:0)-(keys.s?1:0),s=(keys.d?1:0)-(keys.a?1:0),v=(keys.shift?5.6:3.1)*dt/Math.max(1,Math.hypot(f,s));walk(s*v,f*v);}}camera.rotation.set(pitch,yaw,0,'YXZ');let h=Math.max(0,Math.min(6,Math.floor((-camera.position.z+15)/step)));if(h!==current){updateHall(h);loadHall(h);}groups.forEach((g,i)=>g.visible=Math.abs(i-h)<=1);renderer.render(scene,camera);}
updateVisited();initNav();init3D();
